import itertools
import random
import re


def _decimal_parts(token: str) -> tuple[bool, str] | None:
    if re.fullmatch(r"[+-]?[0-9]+", token) is None:
        return None
    digits = token.lstrip("+-").lstrip("0") or "0"
    return token.startswith("-") and digits != "0", digits


def _parse_input(inp: str) -> tuple[int, int, int, list[str]] | None:
    lines = inp.replace("\r\n", "\n").split("\n")
    if lines[-1] == "":
        lines.pop()
    if not lines:
        return None

    header = lines[0].strip(" \t")
    tokens = re.split(r"[ \t]+", header)
    if len(tokens) != 3:
        return None

    values = []
    for token in tokens:
        parts = _decimal_parts(token)
        if parts is None:
            return None
        negative, digits = parts
        if negative or len(digits) > 2:
            return None
        values.append(int(digits))

    height, width, radius = values
    if not (1 <= height <= 10 and 1 <= width <= 10 and height * width >= 2):
        return None
    if not 0 <= radius <= height + width - 2:
        return None

    rows = lines[1:]
    if len(rows) != height:
        return None
    for row in rows:
        if len(row) != width or any(cell not in ".#" for cell in row):
            return None
    if sum(row.count(".") for row in rows) < 2:
        return None
    return height, width, radius, rows


def _format_input(rows: list[str], radius: int) -> str:
    return f"{len(rows)} {len(rows[0])} {radius}\n" + "\n".join(rows) + "\n"


def validate_input(inp: str) -> bool:
    return _parse_input(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    boundaries = [
        "1 2 0\n..\n",
        "2 1 1\n.\n.\n",
        "1 3 2\n.#.\n",
        "1 7 2\n.#.#.#.\n",
        "1 7 1\n.......\n",
        "2 3 1\n.#.\n...\n",
        "2 4 4\n..#.\n.#..\n",
        "2 4 0\n....\n....\n",
        "4 2 1\n.#\n##\n##\n#.\n",
    ]
    cases = boundaries[:max(0, n)]
    rng = random.Random(seed)
    shapes = [
        (height, width)
        for height in range(1, 9)
        for width in range(1, 9)
        if 2 <= height * width <= 8
    ]
    while len(cases) < n:
        height, width = rng.choice(shapes)
        size = height * width
        floors = set(rng.sample(range(size), rng.randint(2, size)))
        rows = [
            "".join("." if row * width + col in floors else "#" for col in range(width))
            for row in range(height)
        ]
        cases.append(_format_input(rows, rng.randint(0, height + width - 2)))
    return cases


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    desks = set(rng.sample(range(100), 8))
    mixed_rows = [
        "".join("#" if row * 10 + col in desks else "." for col in range(10))
        for row in range(10)
    ]
    return [_format_input(["." * 10] * 10, 1), _format_input(mixed_rows, 4)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    parsed = _parse_input(inp)
    if parsed is None:
        return [("POST-1", "Input does not satisfy the grid format or constraints.")]

    tokens = out.split()
    parts = _decimal_parts(tokens[0]) if len(tokens) == 1 else None
    if parts is None:
        return [("POST-2", "Expected exactly one decimal integer token.")]

    height, width, radius, rows = parsed
    floor_count = sum(row.count(".") for row in rows)
    upper = min(floor_count, 2 * (1 + 2 * radius * (radius + 1)))
    negative, digits = parts
    if negative or len(digits) > len(str(upper)):
        return [("POST-4", f"Answer must be between 2 and {upper}.")]

    answer = int(digits)
    if not 2 <= answer <= upper:
        return [("POST-4", f"Answer must be between 2 and {upper}.")]
    if (radius == 0 or floor_count == 2) and answer != 2:
        return [("POST-5", "Zero radius or exactly two floor cells requires an answer of 2.")]
    if radius == height + width - 2 and answer != floor_count:
        return [("POST-5", "The maximum allowed radius covers every floor cell.")]
    return []


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = []

    for index, original in enumerate(gen_small(seed, n)):
        height, width, radius, rows = _parse_input(original)
        variant = index % 3

        if variant == 0:
            transformed = ["".join(column) for column in zip(*rows)]
            if transformed == rows:
                transformed = [row[::-1] for row in rows]
            if transformed == rows:
                transformed = rows + ["#" * width]
            pairs.append(("POST-6", "equal", original, _format_input(transformed, radius)))
        elif variant == 1:
            maximum_radius = height + width - 2
            if radius < maximum_radius:
                larger = rng.randint(radius + 1, maximum_radius)
                pairs.append(("POST-6", "le", original, _format_input(rows, larger)))
            else:
                smaller = rng.randrange(radius)
                pairs.append(("POST-6", "le", _format_input(rows, smaller), original))
        else:
            desks = [
                (row, col)
                for row, cells in enumerate(rows)
                for col, cell in enumerate(cells)
                if cell == "#"
            ]
            if not desks:
                rows = rows + ["#" * width]
                desks = [(height, col) for col in range(width)]
            row, col = rng.choice(desks)
            expanded = rows.copy()
            expanded[row] = rows[row][:col] + "." + rows[row][col + 1:]
            pairs.append((
                "POST-6", "le", _format_input(rows, radius), _format_input(expanded, radius)
            ))

    return pairs


def reference_small(inp: str) -> str | None:
    parsed = _parse_input(inp)
    if parsed is None:
        return None
    height, width, radius, rows = parsed
    if height * width > 25:
        return None

    floors = [
        (row, col)
        for row, cells in enumerate(rows)
        for col, cell in enumerate(cells)
        if cell == "."
    ]
    best = max(
        sum(
            abs(row - first_row) + abs(col - first_col) <= radius
            or abs(row - second_row) + abs(col - second_col) <= radius
            for row, col in floors
        )
        for (first_row, first_col), (second_row, second_col)
        in itertools.combinations(floors, 2)
    )
    return f"{best}\n"
